export const MADE_IN_TIME_INTEREST_TAG = '[Made in Time interest]';
export const MADE_IN_TIME_HELPER_TAG = '[Made in Time helper]';

export function buildMadeInTimeSchedule() {
  return MADE_IN_TIME_MODULES.map((m, i) => ({ ...m, week: i + 1, date: null, weekday: null }));
}

export function madeInTimeProgressSummary(progress = {}) {
  return progressSummaryFor(MADE_IN_TIME_MODULES, progress);
}

export function exportMadeInTimeCurriculumMarkdown() {
  return exportCurriculumMarkdownFor(
    { meta: MADE_IN_TIME_META, sessionFlow: MADE_IN_TIME_SESSION_FLOW, modules: MADE_IN_TIME_MODULES },
    null,
  );
}

